20: function load(){try{const d=JSON.parse(localStorage.getItem(SAVE_KEY));if(d&&d.name)return d}catch{}return null}
21: function save(){if(game) localStorage.setItem(SAVE_KEY,JSON.stringify(game));const s=$('.save-state');if(s){s.innerHTML='<i></i> Saved'}}
22: function log(text,icon='✦'){game.log.unshift({age:game.age,year:game.year,icon,text});game.log=game.log.slice(0,30)}
23: function clamp(v){return Math.max(0,Math.min(100,Math.round(v)))}
24: function spend(){if(game.energy<=0){toast('You are out of actions this year. Let time pass.');return false}game.energy--;return true}
25: function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
26: function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
27: function statCard(label,key){return `<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon">${icons[key]}</span></div><div class="stat-value">${game[key]}<small> / 100</small></div><div class="meter ${key==='health'?'red':key==='happiness'?'gold':''}"><span style="width:${game[key]}%"></span></div></div>`}
28: function profileCard(){return `<section class="card"><div class="profile-row"><div class="avatar">${game.vampire?'🧛':game.wolf?'🐺':game.origin==='noble'?'🧝‍♀️':'🧙'}</div><div><strong>${esc(game.name)}</strong><p>${esc(game.title)} · Age ${game.age}</p></div></div><div class="divider"></div><div class="detail-row"><span>Coin purse</span><strong class="coin">◈ ${game.money.toLocaleString()}</strong></div><div class="detail-row"><span>Home</span><strong>${game.land[0]?.name||'Briar Glen'}</strong></div><div class="detail-row"><span>Reputation</span><strong>${game.reputation<20?'Little known':game.reputation<55?'Known in the March':game.reputation<85?'A name at court':'A living legend'}</strong></div>${game.bounty>0?`<div class="detail-row"><span>Wanted</span><strong style="color:var(--red)">◈ ${game.bounty} bounty</strong></div>`:''}</section>`}
29: function actionButtons(){const acts=[['📖','Study lore','Intellect +'],['🗡️','Train with Oren','Health +'],['🌿','Gather herbs','Earn a little'],['🎭','Perform in town','Charm +'],['🕯️','Meditate','Arcana +'],['🛌','Rest & recover','Health +']];return acts.map((a,i)=>`<button class="action-btn" data-action="${['study','train','gather','perform','meditate','rest'][i]}"><span class="emoji">${a[0]}</span><strong>${a[1]}</strong><small>${a[2]}</small></button>`).join('')}
30: function lifeView(){const last=game.log.slice(0,4);return `<div class="layout"><div class="left-column"><section class="hero"><div class="hero-content"><div class="eyebrow">Briar March · Year ${game.year}</div><h1>Your story is<br>yours to shape.</h1><p>In a land of old blood and older magic, every choice leaves a mark. What will yours be?</p><div class="hero-meta"><span class="chip gold">${esc(game.title)}</span><span class="chip">${game.vampire?'☾ Vampire':game.wolf?'☾ Werewolf':game.magic.Blood?'✧ Blood-touched':'✦ Mortal'}</span>${game.partner?`<span class="chip">♡ ${esc(game.partner)}</span>`:''}</div></div></section><div class="stats-grid">${statCard('Health','health')}${statCard('Happiness','happiness')}${statCard('Intellect','intellect')}${statCard('Charm','charm')}</div><section class="card"><div class="card-heading"><h2>Spend this year</h2><span class="subtle">${game.energy} action${game.energy===1?'':'s'} left</span></div><div class="life-actions">${actionButtons()}</div><div class="divider"></div><div class="year-row"><span class="hint">The years pass whether you are ready or not.</span><button class="year-btn" data-action="age">Live another year →</button></div></section><section class="card"><div class="card-heading"><h2>Chronicle</h2><span class="subtle">Your life, so far</span></div><div class="log-list">${last.map(e=>`<div class="log-entry"><div class="log-icon">${e.icon}</div><div><time>AGE ${e.age} · YEAR ${e.year}</time><p>${esc(e.text)}</p></div></div>`).join('')}</div></section></div><aside class="right-column">${profileCard()}<section class="card"><div class="card-heading"><h2>Those close to you</h2><button class="small-btn" data-tab="people">All people ↗</button></div>${game.people.filter(p=>p.alive).slice(0,3).map(p=>`<div class="mini-person"><div class="avatar">${p.emoji}</div><div><strong>${esc(p.name)}</strong><p>${esc(p.role.split('·')[0])}</p></div><span class="affinity">♡ ${p.affinity}</span></div>`).join('')}</section><section class="... (line truncated to 2000 chars)
31: function peopleView(){return `<div class="section-header"><div><div class="eyebrow">Your circle</div><h1>People & Bonds</h1><p>Friendships are made, broken, and remembered.</p></div><span class="tag">${game.people.filter(p=>p.alive).length} living</span></div><div class="section-grid">${game.people.map(p=>`<section class="card person-card" style="${!p.alive?'opacity:.5':''}"><div class="avatar">${p.alive?p.emoji:'🪦'}</div><div class="person-info"><strong>${esc(p.name)} ${p.partner?'♡':''}</strong><p>${p.alive?esc(p.role):'Deceased'}</p><div class="progress-line"><span class="subtle">Bond</span><div class="meter"><span style="width:${p.affinity}%;background:${p.affinity>65?'var(--green)':p.affinity<30?'var(--red)':'var(--gold)'}"></span></div><span class="subtle">${p.affinity}</span></div></div><div style="position:absolute;right:auto"></div><div class="relationship-actions" style="position:absolute;display:none"></div><div class="person-actions">${p.alive?`<div class="relationship-actions"><button class="small-btn" data-person="${p.id}" data-action="talk">Talk</button><button class="small-btn" data-person="${p.id}" data-action="gift">Gift ◈20</button><button class="small-btn" data-person="${p.id}" data-action="romance">${game.partner===p.name?'Partner':'Flirt'}</button><button class="small-btn" data-person="${p.id}" data-action="harm">⚔ Attack</button></div>`:`<div class="relationship-actions"><span class="tag">Remembered</span></div>`}</div></section>`).join('')}</div>`}
