34: function realmView(){let land=properties.filter(x=>!game.land.some(l=>l.name===x.name));let own=game.land;let shops=ventures.filter(x=>!game.businesses.some(b=>b.name===x.name));return `<div class="section-header"><div><div class="eyebrow">A place in the world</div><h1>Realm & Fortune</h1><p>Make a home, build an enterprise, rise above your birth.</p></div><span class="tag">◈ ${game.money.toLocaleString()}</span></div><div class="section-grid"><section class="card"><div class="card-heading"><h2>Claim your ground</h2><span class="subtle">Land & title</span></div>${own.length?own.map(l=>`<div class="estate-item"><div class="estate-icon">${l.icon}</div><div><strong>${esc(l.name)}</strong><p>${l.income?`Income ◈${l.income}/year`:'A place to call home'}</p></div><span class="tag">Owned</span></div>`).join(''):'<p class="empty">You own no land yet. A foothold in the March can change everything.</p>'}${land.length?land.map(l=>`<div class="estate-item"><div class="estate-icon">${l.icon}</div><div><strong>${l.name}</strong><p>${l.desc}</p></div><button class="small-btn" data-buy="property:${l.name}">◈ ${l.price}</button></div>`).join(''):'<p class="empty">Every available holding is yours.</p>'}<div class="divider"></div><div class="card-heading"><h2>Earn a title</h2></div><p class="empty">Titles are not bought; they are earned through wealth, service, and audacity.</p><div class="option-list"><button class="option" data-action="petition"><span class="option-icon">👑</span><span><strong>Petition the duke</strong><small>Seek a place in the nobility.</small></span><span class="price">${game.title==='Villager'?'Try':'—'}</span></button><button class="option" data-action="guild"><span class="option-icon">⚜️</span><span><strong>Join the merchant guild</strong><small>Requires a business or ◈300.</small></span></button></div></section><section class="card"><div class="card-heading"><h2>Build your livelihood</h2><span class="subtle">Businesses</span></div>${game.businesses.length?gam... (line truncated to 2000 chars)
35: const schools=[{name:'Ember',icon:'🔥',desc:'Shape flame, light, and fierce will.',spell:'Cinderbolt'},{name:'Tide',icon:'🌊',desc:'Mend wounds and command flowing water.',spell:'Mending rain'},{name:'Veil',icon:'🌙',desc:'Bend shadows, dreams, and attention.',spell:'Whisper veil'},{name:'Blood',icon:'🩸',desc:'An ancient art with a terrible price.',spell:'Sanguine pact'}];
36: function arcanaView(){return `<div class="section-header"><div><div class="eyebrow">The unseen world</div><h1>Arcana & Change</h1><p>Magic answers those who dare to ask the right questions.</p></div><span class="tag">✧ ${game.arcana} arcana</span></div><div class="section-grid"><section class="card"><div class="card-heading"><h2>Schools of magic</h2><span class="subtle">Study to unlock spells</span></div><div class="option-list">${schools.map(s=>`<div class="option" style="cursor:default"><span class="option-icon">${s.icon}</span><span style="flex:1"><strong>${s.name} magic · ${game.magic[s.name]}</strong><small>${s.desc}</small><div class="meter" style="margin-top:8px"><span style="width:${Math.min(100,game.magic[s.name]*25)}%"></span></div></span><button class="small-btn" data-school="${s.name}">${game.magic[s.name]?'Practice':'Learn'}</button></div>`).join('')}</div><div class="divider"></div><div class="card-heading"><h2>Known spells</h2></div><div class="spell-grid">${schools.filter(s=>game.magic[s.name]>0).map(s=>`<div class="spell"><strong>${s.icon} ${s.spell}</strong><p>${s.name==='Tide'?'Restore health through a whispered charm.':s.name==='Veil'?'Wrap yourself in an illusion; charm and cunning follow.':s.name==='Blood'?'Trade vitality for a surge of power.': 'A controlled spark that can change your luck.'}</p><button data-cast="${s.name}">Cast · 1 action</button></div>`).join('')||'<p class="empty">No spells learned yet. Study a school to begin.</p>'}</div></section><section class="card"><div class="card-heading"><h2>Beyond mortality</h2></div><p class="empty">The old powers are real. They do not give gifts without changing the giver.</p><div class="option-list"><button class="option" data-action="wolf"><span class="option-icon">🐺</span><span><strong>${game.wolf?'Embrace the beast':'Seek the moon-bite'}</strong><small>${game.wolf?'You are bound to the moon.':'Find the white wolf in the Briarwood.'}</small></span><span class="price">${game.wolf?'Bound':'See... (line truncated to 2000 chars)
37: function render(){const root=$('#app');if(!game){root.innerHTML=`<div class="death-screen"><div class="symbol">✦</div><div class="eyebrow">The Briar March awaits</div><h1>A life unwritten.</h1><p>Build a legacy in a world of old magic, hungry ambition, and impossible choices.</p><button class="year-btn" data-action="newgame">Begin your story →</button></div>`;updateNav();return}if(!game.alive){root.innerHTML=deathView();updateNav();return}root.innerHTML=currentTab==='life'?lifeView():currentTab==='people'?peopleView():currentTab==='realm'?realmView():arcanaView();updateNav()}
38: function updateNav(){$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab))}
39: function deathView(){return `<div class="death-screen"><div class="symbol">✦</div><div class="eyebrow">A life remembered</div><h1>${esc(game.name)}’s story ends.</h1><p>At age ${game.age}, in the year ${game.year}, the candle guttered. But stories outlive their tellers.</p><div class="legacy-stats"><div><strong>${game.age}</strong><small>YEARS LIVED</small></div><div><strong>◈ ${game.money}</strong><small>FINAL FORTUNE</small></div><div><strong>${game.title}</strong><small>FINAL TITLE</small></div></div><button class="year-btn" data-action="newgame">Begin a new life →</button></div>`}
40: function modal(title,intro,body,buttons=''){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><p class="intro">${intro}</p>${body}${buttons?`<div class="modal-actions">${buttons}</div>`:''}</div></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''})}
41: function startModal(){modal('Choose your beginning','Your first chapter is written in Briar Glen. The rest is yours.','<label>Your name</label><input id="new-name" maxlength="24" value="Aerin Vale"><label>Origin</label><div class="choice-grid">'+Object.entries(archetypes).map(([k,o],i)=>`<button class="choice ${i===0?'selected':''}" data-origin="${k}"><strong>${o.label}</strong><small>${o.desc}</small></button>`).join('')+'</div><label>Pronouns</label><select id="pronouns"><option>they/them</option><option>she/her</option><option>he/him</option></select>','<button class="secondary-btn" data-close>Not now</button><button class="year-btn" data-create>Begin life →</button>')}
42: function handleAction(action,el){if(!game){if(action==='newgame')startModal();return}if(action==='newgame'){startModal();return}if(action==='age'){ageUp();return}if(['study','train','gather','perform','meditate','rest','work'].includes(action)){if(!spend())return;switch(action){case'study':game.intellect=clamp(game.intellect+5);game.happiness=clamp(game.happiness-1);log('You spent long evenings with a borrowed book. The world’s secrets feel a little closer.','📖');break;case'train':game.health=clamp(game.health+5);game.intellect=clamp(game.intellect+1);log('Oren put you through drills until your arms shook. You are stronger for it.','🗡️');break;case'gather':game.money+=18;game.health=clamp(game.health-1);log('You gathered herbs in the woods and sold them at market for 18 coins.','🌿');break;case'perform':game.charm=clamp(game.charm+4);game.money+=8;log('You told stories in the tavern. A few coins and a little fame were yours.','🎭');break;case'meditate':game.arcana++;game.happiness=clamp(game.happiness+2);log('You sat beneath the standing stones. Something in the air answered your thoughts.','🕯️');break;case'rest':game.health=clamp(game.health+13);game.happiness=clamp(game.happiness+4);log('You took a quiet year to recover and enjoy the simple things.','🛌');break;case'work':game.money+=35;game.happiness=clamp(game.happiness-2);log('You took honest work in the village and earned 35 coins.','🪙');break}save();render();return}
43:  if(action==='petition'){if(!spend())return;let chance=game.reputation+game.charm+(game.land.length*12)+(game.businesses.length*10)+(game.origin==='noble'?18:0);if(chance>95){game.title=game.title==='Villager'?'Landed Knight':game.title==='Landed Knight'?'Baron':'Duke’s Favorite';game.reputation+=20;game.money+=90;log(`Duke Aldric granted you the title of ${game.title}. The court has a new name to remember.`,'👑');toast('You have risen in station!')}else{game.reputation+=4;game.happiness=clamp(game.happiness+2);log('You petitioned the duke. He praised your ambition but asked you to prove your worth first.','👑');toast('Build wealth and reputation, then petition again.')}save();render();return}
44:  if(action==='guild'){if(game.businesses.length||game.money>=300){if(!spend())return;game.title=game.title==='Villager'?'Guild Member':game.title;game.reputation+=8;log('The merchants welcomed you into their guild. Your name now carries weight in the market.','⚜️');toast('You joined the guild!')}else toast('You need a business or ◈300 to join.');save();render();return}
45:  if(action==='wolf'){if(game.wolf){toast('The moon-bite is already part of you.');return}if(!spend())return;game.health=clamp(game.health-8);game.wolf=true;game.happiness=clamp(game.happiness+9);game.reputation-=2;log('In the deep Briarwood, a white wolf found you. Its bite burned like winter. You awoke changed.','🐺');toast('The wolf-spirit lives in you.');save();render();return}
46:  if(action==='vampire'){if(game.vampire){toast('The night has already claimed you.');return}if(!spend())return;game.health=clamp(game.health-15);game.vampire=true;game.happiness=clamp(game.happiness-5);game.magic.Blood=Math.max(1,game.magic.Blood);game.arcana++;log('Elara offered you a crimson draught. The heart stopped, then began again to a different rhythm. You are no longer mortal.','🦇');toast('You have become a vampire.');save();render();return}
47:  if(action==='talk'||action==='gift'||action==='romance'||action==='harm'){personAction(el.dataset.person,action);return}}
48: function ageUp(){if(!game)return;game.age++;game.year++;game.energy=3;let income=[...game.land,...game.businesses].reduce((n,x)=>n+(x.income||0),0);game.money+=income;if(game.vampire)game.health=clamp(game.health+2);else game.health=clamp(game.health-(game.age>65?7:2));game.happiness=clamp(game.happiness+(game.partner?2:0)-(game.bounty?2:0));if(game.wolf&&Math.random()<.2){game.happiness=clamp(game.happiness-5);log('The full moon came. The beast inside you is restless.','🌕')}if(game.bounty>0&&Math.random()<.25){game.bounty=Math.max(0,game.bounty-10);log('The local guards searched for you, but your trail has grown cold.','🛡️')}
49:  if(game.age>=90&&!game.vampire){game.health=clamp(game.health-4)}if(game.health<=0||game.age>105&&!game.vampire){game.alive=false;log('Your story came to its end. The March will remember what you made of your years.','🕯️')}else{let event;if(game.age===20)event='You came of age. The villagers now look to you as an adult.';else if(game.age===30)event='A decade has passed. You begin to understand what kind of life you are building.';else if(game.age===50)event='The years have shaped you. Younger folk ask for your counsel.';else if(game.age===70&&!game.vampire)event='Age settles into your bones. You have lived more than most.';else if(game.age===25&&game.origin==='noble')event='A letter from a distant cousin reminds you: your family name still means something.';else if(income)event=`Your holdings earned ${income} coins while you went about your life.`;else event='Another year turns. Somewhere beyond the hills, the old powers stir.';log(event,income?'◈':'⌛')}save();render()}
50: function personAction(id,action){const p=game.people.find(x=>x.id===id);if(!p||!p.alive){toast('There is no one there.');return}if(action==='talk'){if(!spend())return;const lines=[`You shared a quiet conversation with ${p.name}.`,`You asked ${p.name} about their hopes. They seemed glad you listened.`,`You and ${p.name} traded stories until the hour grew late.`];p.affinity=clamp(p.affinity+7);game.happiness=clamp(game.happiness+2);log(lines[Math.floor(Math.random()*lines.length)],'♙');toast(`${p.name} feels closer to you.`)}else if(action==='gift'){if(game.money<20){toast('You cannot afford a gift.');return}if(!spend())return;game.money-=20;p.affinity=clamp(p.affinity+14);log(`You gave ${p.name} a thoughtful gift. Their face lit up.`,'🎁');toast('A bond strengthened.')}else if(action==='romance'){if(game.partner===p.name){toast(`${p.name} is already your partner.`);return}if(p.affinity<50){toast('Build a closer bond before you court them.');return}if(!spend())return;game.partner=p.name;p.affinity=clamp(p.affinity+12);game.happiness=clamp(game.happiness+9);log(`You confessed your feelings to ${p.name}. They took your hand. A new chapter begins.`,'♡');toast(`You and ${p.name} are together.`)}else if(action==='harm'){harmPerson(p)}save();render()}
51: function harmPerson(p){if(!spend())return;const chance=game.charm+game.intellect+(game.title==='Villager'?0:15);if(chance>80){p.alive=false;game.reputation-=14;game.bounty+=50;log(`You made a terrible choice and ${p.name} died. The March will not forget. The guards are searching for you.`,'⚔️');toast('A life ended. You are now wanted.')}else{p.affinity=clamp(p.affinity-22);game.health=clamp(game.health-8);game.bounty+=15;log(`You confronted ${p.name}, but it turned violent. You fled before the guards arrived.`,'⚔️');toast('The confrontation went badly.')}save();render()}
52: function buyThing(kind,name){const list=kind==='property'?properties:ventures;const item=list.find(x=>x.name===name);if(!item)return;if(game.money<item.price){toast('Not enough coin.');return}game.money-=item.price;const own={name:item.name,icon:item.icon,income:item.income};(kind==='property'?game.land:game.businesses).push(own);game.reputation+=kind==='property'?5:7;if(item.name==='Manor of Ashford'&&game.title==='Villager'){game.title='Landed Gentry';game.reputation+=12}log(`You purchased ${item.name} for ${item.price} coins.${item.income?` It will earn ◈${item.income} each year.`:''}`,'⌂');toast(`${item.name} is yours.`);save();render()}
