 function render(){const root=$('#app');if(!game){root.innerHTML=`<div class="death-screen"><div class="symbol">✦</div><div class="eyebrow">The Briar March awaits</div><h1>A life unwritten.</h1><p>Build a legacy in a world of old magic, hungry ambition, and impossible choices.</p><button class="year-btn" data-action="newgame">Begin your story →</button></div>`;updateNav();return}if(!game.alive){root.innerHTML=deathView();updateNav();return}root.innerHTML=currentTab==='life'?lifeView():currentTab==='people'?peopleView():currentTab==='realm'?realmView():arcanaView();updateNav()}
 function updateNav(){$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab))}
