 function handleAction(action,el){if(!game){if(action==='newgame')startModal();return}if(action==='newgame'){startModal();return}if(action==='age'){ageUp();return}if(action==='customize'){customizeModal();return}if(['study','train','gather','perform','meditate','rest','work','explore','create','volunteer','write','travel','celebrate'].includes(action)){if(!spend())return;switch(action){case'study':game.intellect=clamp(game.intellect+5);game.happiness=clamp(game.happiness-1);log('You spent long evenings with a borrowed book. The world’s secrets feel a little closer.','📖');break;case'train':game.health=clamp(game.health+5);game.intellect=clamp(game.intellect+1);log('Oren put you through drills until your arms shook. You are stronger for it.','🗡️');break;case'gather':game.money+=18;game.health=clamp(game.health-1);log('You gathered herbs in the woods and sold them at market for 18 coins.','🌿');break;case'perform':game.charm=clamp(game.charm+4);game.money+=8;log('You told stories in the tavern. A few coins and a little fame were yours.','🎭');break;case'meditate':game.arcana++;game.happiness=clamp(game.happiness+2);log('You sat beneath the standing stones. Something in the air answered your thoughts.','🕯️');break;case'rest':game.health=clamp(game.health+13);game.happiness=clamp(game.happiness+4);log('You took a quiet year to recover and enjoy the simple things.','🛌');break;case'work':game.money+=35;game.happiness=clamp(game.happiness-2);log('You took honest work in the village and earned 35 coins.','🪙');break;case'explore':{const finds=[['You followed a blue butterfly trail to a quiet waterfall. The journey lifted your spirits.','🦋',()=>game.happiness=clamp(game.happiness+9)],['A peddler paid you to guide their cart home.','🧭',()=>game.money+=28],['You found a forgotten book beneath the roots of an old tree.','📚',()=>game.intellect=clamp(game.intellect+4)],['You returned with a pocketful of moonstones.','💎',()=>game.money+=18]];const f=finds[Math.floor(Math.random()*finds.length)];f[2]();log(f[0],f[1]);break}case'create':game.happiness=clamp(game.happiness+7);game.charm=clamp(game.charm+2);game.reputation+=2;log('You painted, stitched, carved, or composed—whatever your heart wanted. Someone in town loved your creation.','🎨');break;case'volunteer':game.happiness=clamp(game.happiness+5);game.reputation+=4;game.people.find(p=>p.alive).affinity=clamp(game.people.find(p=>p.alive).affinity+3);log('You helped with a village project. The neighbors made sure you knew you were appreciated.','🤝');break;case'write':game.intellect=clamp(game.intellect+4);game.happiness=clamp(game.happiness+3);log('You filled a journal page with a memory, a poem, or a plan for the future.','✍️');break;case'travel':if(game.money>=12&&Math.random()<.65){game.money-=12;game.reputation+=3;log('You took the road to a neighboring town, tried its famous pastries, and came home with new stories.','🚌')}else{game.happiness=clamp(game.happiness+4);log('You wandered the lanes nearby and found a lovely place to watch the sunset.','🌸')}break;case'celebrate':game.happiness=clamp(game.happiness+8);game.people.filter(p=>p.alive).slice(0,2).forEach(p=>p.affinity=clamp(p.affinity+4));game.money=Math.max(0,game.money-10);log('You invited friends for a little celebration. There was music, too much cake, and no regrets.','🎉');break}save();render();return}
  if(action==='petition'){if(!spend())return;let chance=game.reputation+game.charm+(game.land.length*12)+(game.businesses.length*10)+(game.origin==='noble'?18:0);if(chance>95){game.title=game.title==='Villager'?'Landed Knight':game.title==='Landed Knight'?'Baron':'Duke’s Favorite';game.reputation+=20;game.money+=90;log(`Duke Aldric granted you the title of ${game.title}. The court has a new name to remember.`,'👑');toast('You have risen in station!')}else{game.reputation+=4;game.happiness=clamp(game.happiness+2);log('You petitioned the duke. He praised your ambition but asked you to prove your worth first.','👑');toast('Build wealth and reputation, then petition again.')}save();render();return}
  if(action==='guild'){if(game.businesses.length||game.money>=300){if(!spend())return;game.title=game.title==='Villager'?'Guild Member':game.title;game.reputation+=8;log('The merchants welcomed you into their guild. Your name now carries weight in the market.','⚜️');toast('You joined the guild!')}else toast('You need a business or ◈300 to join.');save();render();return}
  if(action==='wolf'){if(game.wolf){toast('The moon-bite is already part of you.');return}if(!spend())return;game.health=clamp(game.health-8);game.wolf=true;game.happiness=clamp(game.happiness+9);game.reputation-=2;log('In the deep Briarwood, a white wolf found you. Its bite burned like winter. You awoke changed.','🐺');toast('The wolf-spirit lives in you.');save();render();return}
